count(*),''sha256'',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),''[]'')::text,''UTF8'')),''hex'')) from public.finance_treasury_authority_audit r)),(''finance_vp_revenue_distribution_audit'',(select jsonb_build_object(''count'',count(*),''sha256'',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),''[]'')::text,''UTF8'')),''hex'')) from public.finance_vp_revenue_distribution_audit r)),(''finance_vp_revenue_distributions'',(select jsonb_build_object(''count'',count(*),''sha256'',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),''[]'')::text,''UTF8'')),''hex'')) from public.finance_vp_revenue_distributions r)),(''user_profiles'',(select jsonb_build_object(''count'',count(*),''sha256'',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(r) order by (to_jsonb(r))::text collate "C"),''[]'')::text,''UTF8'')),''hex'')) from public.user_profiles r))) data(name,hash)) r';
