$candidate066$;
BEGIN
 IF encode(sha256(convert_to(candidate_sql,'UTF8')),'hex') <> '010093343be8675823b8e9459c979d1dc6efe75959c7f12c0268eecb17db3f9e' THEN
  RAISE EXCEPTION '066 CANDIDATE SHA MISMATCH';
 END IF;
 EXECUTE capture_sql INTO actual_state;
 select coalesce(jsonb_agg(jsonb_build_object('section',s,'object',k,'expected',expected_before->s->k,'actual',actual_state->s->k) order by s,k),'[]')
from unnest(array['functions','catalog','rows']) s
cross join lateral (select jsonb_object_keys(expected_before->s) k union select jsonb_object_keys(actual_state->s) k) keys
where actual_state->s->k is distinct from expected_before->s->k INTO failures;
 IF failures <> '[]'::jsonb THEN RAISE EXCEPTION '066 SCOPED PRECONDITIONS FAILED: %',failures; END IF;
 -- Exact candidate execution: no wrapper edits, reconstructed DDL or UAT writes.
 EXECUTE candidate_sql;
 SET CONSTRAINTS ALL IMMEDIATE;
 EXECUTE capture_sql INTO actual_state;
 select coalesce(jsonb_agg(jsonb_build_object('section',s,'object',k,'expected',expected_after->s->k,'actual',actual_state->s->k) order by s,k),'[]')
from unnest(array['functions','catalog','rows']) s
cross join lateral (select jsonb_object_keys(expected_after->s) k union select jsonb_object_keys(actual_state->s) k) keys
where actual_state->s->k is distinct from expected_after->s->k INTO failures;
 IF exists(select 1 from public.finance_combined_documents where direct_money_receipt_id is not null) or exists(select 1 from public.finance_receipt_invoice_allocations where direct_money_receipt_id is not null or direct_source_line_id is not null) or exists(select 1 from public.finance_receipts where direct_money_receipt_id is not null) or exists(select 1 from public.finance_tax_document_corrections where direct_money_receipt_id is not null) or exists(select 1 from public.finance_tax_invoice_items where direct_money_receipt_id is not null or direct_source_line_id is not null) or exists(select 1 from public.finance_tax_invoice_source_coverages where direct_money_receipt_id is not null or direct_source_line_id is not null) or exists(select 1 from public.finance_tax_invoices where direct_money_receipt_id is not null) THEN failures:=failures||jsonb_build_array(jsonb_build_object('section','rows','object','historical_new_source_columns','expected','all null')); END IF;
 IF failures <> '[]'::jsonb THEN RAISE EXCEPTION '066 POST-MIGRATION ASSERTIONS FAILED: %',failures; END IF;
END;
